        if (info == null)
            System.out.println("Info is null");
        if (info.isSet(MyConstants.M_NO_CONTENT_DESCRIPTION))
            return null;

        // Case 2: Second condition calls method on a different variable - should not merge
        ResourceInfo otherInfo = new ResourceInfo();
        if (info == null)
            return null;
        if (otherInfo.isSet(MyConstants.M_NO_CONTENT_DESCRIPTION))
            return null;

        return new Object();
    }
}

